/// <summary>
/// VendInvoiceInfoLine table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoLine))]
final class METVendInvoiceInfoLine_Extension
{
}

Method.Source:
    /// <summary>
    /// FieldId modified logic
    /// </summary>
    /// <param name = "_fieldId">FieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        ReasonTableRef  metReasonTableRef;
        ReasonTable reasonTable;
        switch(_fieldId)
        {
            case fieldNum(VendInvoiceInfoLine, ReceiveNow):
            case fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow):           
            case fieldNum(VendInvoiceInfoLine, PurchPrice):
                if(!this.isNonPO())
                {
                    this.metFetchInitializeReasonCode();
                }
                break;
            case fieldNum(VendInvoiceInfoLine, ReasonTableRef):
                metReasonTableRef  = ReasonTableRef::find(this.ReasonTableRef);
                reasonTable = ReasonTable::find(metReasonTableRef.Reason);
                this.metInitReasonCode(reasonTable, reasonTable.RecId ? true : false);
                break;
            case fieldNum(VendInvoiceInfoLine, MetPriceVarianceReasonCode):
                metReasonTableRef  = ReasonTableRef::find(this.MetPriceVarianceReasonCode);
                reasonTable = ReasonTable::find(metReasonTableRef.Reason);
                this.metInitReasonCode(reasonTable, reasonTable.RecId ? true : false);
                break;
            case fieldNum(VendInvoiceInfoLine, TaxItemGroup):
                this.metUpdateMarkupTransTaxItemGroup();
                break;
        }
    }

    /// <summary>
    /// Update TaxItemGroup
    /// </summary>
    public void metUpdateMarkupTransTaxItemGroup()
    {
        MarkupTrans         markupTrans;
        MarkupTable         markupTable;

        update_recordset markupTrans
            setting TaxItemGroup = this.TaxItemGroup
            exists join markupTable
            where markupTable.MarkupCode    == markupTrans.MarkupCode
            && markupTable.TaxItemGroup     == ''
            && markupTrans.TransTableId     == tableNum(VendInvoiceInfoLine)
            && markupTrans.TransRecId       == this.RecId
            && markupTrans.TaxItemGroup     != this.TaxItemGroup;
    }

    /// <summary>
    /// Edit method for quantity reason code
    /// </summary>
    /// <param name = "_set">booelan</param>
    /// <param name = "_reasonCode">reasoncode</param>
    /// <returns>ReasonCode</returns>
    public edit ReasonCode editReasonCode(boolean _set, ReasonCode _reasonCode)
    {
        ReasonCode metReasonCode = next editReasonCode(_set, _reasonCode);

        if(_set)
        {
            this.modifiedField(fieldNum(VendInvoiceInfoLine, ReasonTableRef));
        }

        return metReasonCode;
    }

    /// <summary>
    /// Edit method for price reason code
    /// </summary>
    /// <param name = "_set">booelan</param>
    /// <param name = "_reasonCode">reasoncode</param>
    /// <returns>ReasonCode</returns>
    public edit ReasonCode editPriceReasonCode(boolean _set, ReasonCode _reasonCode)
    {
        ReasonCode metReasonCode = ReasontableRef::find(this.MetPriceVarianceReasonCode).Reason;

        if(_set)
        {
            this.modifiedField(fieldNum(VendInvoiceInfoLine, MetPriceVarianceReasonCode));
        }

        return metReasonCode;
    }

private METVarianceType metGetQuantityVarianceType()
{
    return (this.ReceiveNow > this.purchQtyMatched() || this.PdsCWReceiveNow > this.pdsCWQtyMatched()) ? METVarianceType::QuantityVarianceOver : METVarianceType::QuantityVarianceUnder;
}

private METVarianceType metGetPriceVarianceType()
{
    return this.priceVariancePercent() > 0 ? METVarianceType::PriceVarianceOver : METVarianceType::PriceVarianceUnder;
}

    private ReasonTable metGetVarianceReasonCodes(METVarianceCategory _varianceCategory)
    {
        ReasonTable retReasonCode;
        METVarianceType varianceType;

        if(_varianceCategory == METVarianceCategory::Price)
        {
            varianceType = this.metGetPriceVarianceType();
        }
        else
        {
            varianceType = this.metGetQuantityVarianceType();
        }

        retReasonCode = ReasonTable::metFindReasonCodeForVarianceType(varianceType);

        return retReasonCode;
    }

    /// <summary>
    /// Initialise reasoncode
    /// </summary>
    /// <param name = "_useCatchWeight">True to use catchWeight; else false</param>
    private void metFetchInitializeReasonCode()
    {
        if (this.checkIfQuantityMatch() == LastMatchVarianceOptions::Warning)
        {        
            this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Quantity), true);
        }
        else
        {
            this.ReasonTableRef = 0;
        }

        if (this.priceVarianceStatus() == LastMatchVarianceOptions::Warning)
        {
            this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Price), true);
        }
        else
        {
            this.MetPriceVarianceReasonCode = 0;
        }
    }

   /// <summary>
   /// Initialise or create reasoncode
   /// </summary> 
   /// <param name = "_reasonCode">ReasonCode</param>
   /// <param name = "_create">true if new record to be created; otherwise false</param>
    private void metInitReasonCode(ReasonTable _reasonCode, boolean _create = false)
    {
        if(_reasonCode && _create)
        {
            if(_reasonCode.METVarianceType == METVarianceType::PriceVarianceOver || _reasonCode.METVarianceType == METVarianceType::PriceVarianceUnder)
            {
                this.MetPriceVarianceReasonCode = ReasonTableRef::createReasonTableRef(_reasonCode.Reason, _reasonCode.Description);
            }
            else if(_reasonCode.METVarianceType == METVarianceType::QuantityVarianceOver || _reasonCode.METVarianceType == METVarianceType::QuantityVarianceUnder)
            {
                this.ReasonTableRef = ReasonTableRef::createReasonTableRef(_reasonCode.Reason, _reasonCode.Description);
            }

            this.MetAutoApprove = _reasonCode.METApprove;
            this.MetClaimLine   = _reasonCode.METClaim;
            this.MetExtComment  = _reasonCode.MetExtComment;
        }
        else
        {
            this.ReasonTableRef = 0;
            this.MetPriceVarianceReasonCode = 0;
        }
    }

    /// <summary>
    /// Initialise VendInvoiceInfoLine, price variance line
    /// </summary>
    /// <param name = "_vendInvoiceInfoLine">VendInvoiceInfoLine</param>
    /// <param name = "_reasonTable">ReasonTable</param>
    /// <param name = "_isQtyFailure">True if Qty failure; otherwise false</param>
    /// <param name = "_isCatchWeight">True if Qty failure; otherwise false</param>
    public void metInitPriceFailureMatchingLine(VendInvoiceInfoLine _vendInvoiceInfoLine, ReasonTable _reasonTable, boolean _isCatchWeight)
    {
        PurchLine               purchLine               = _vendInvoiceInfoLine.purchLine();
        InventTable             inventTable             = this.inventTable();
        InventQty               toReceiveNowInvent;
        int                     factor;

        this.clear();
        this.initValue();

        this.ParmId                 = _vendInvoiceInfoLine.ParmId;
        this.TableRefId             = _vendInvoiceInfoLine.TableRefId;
        this.currencyCode           = _vendInvoiceInfoLine.currencyCode;
        this.AddressRefRecId        = _vendInvoiceInfoLine.AddressRefRecId;
        this.AddressRefTableId      = _vendInvoiceInfoLine.AddressRefTableId;
        this.DeliveryName           = _vendInvoiceInfoLine.DeliveryName;
        this.DeliveryPostalAddress  = _vendInvoiceInfoLine.DeliveryPostalAddress;
        this.MetTransRefId          = _vendInvoiceInfoLine.RecId;
        this.InventDimId            = _vendInvoiceInfoLine.InventDimId;
        this.OrigPurchId            = _vendInvoiceInfoLine.OrigPurchId;

        this.ItemId                 = _reasonTable.METItem;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));
        this.TaxGroup               = _vendInvoiceInfoLine.TaxGroup;
        this.TaxItemGroup           = _vendInvoiceInfoLine.TaxItemGroup;
        this.DefaultDimension       = purchLine.DefaultDimension;

        this.MetClaimLine           = _reasonTable.METClaim;
        this.MetAutoApprove         = _reasonTable.METApprove;
        this.MetExtComment          = _reasonTable.MetExtComment;
        this.METVarianceItemId      = _vendInvoiceInfoLine.ItemId;
        this.METPriceVarianceReal   = _vendInvoiceInfoLine.displayPriceVariance();
        this.METQuantityVariance    = _vendInvoiceInfoLine.displayQuantityVariance();
        this.METCWQuantityVariance  = _vendInvoiceInfoLine.displayCWQuantityVariance();

        this.ReasonTableRef         = ReasonTableRef::createReasonTableRef(_reasonTable.Reason, _reasonTable.Description);
        this.Description            = strFmt("@MET:PlaceHolder", _vendInvoiceInfoLine.VendDocumentLineMap::name(), _reasonTable.MetExtComment);
        boolean qtyFailure = _reasonTable.METVarianceType == METVarianceType::QuantityVarianceOver || _reasonTable.METVarianceType == METVarianceType::QuantityVarianceUnder;

        if(qtyFailure)
        {
            this.PurchPrice = _vendInvoiceInfoLine.PurchPrice;
        }
        else
        {
            this.PurchPrice = abs(_vendInvoiceInfoLine.PurchPrice - purchLine.PurchPrice);
        }
        
        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        if(qtyFailure)
        {
            if(!_isCatchWeight)
            {
                this.ReceiveNow = _vendInvoiceInfoLine.ReceiveNow - _vendInvoiceInfoLine.purchQtyMatched();
            }
            else
            {
                this.PdsCWReceiveNow    = _vendInvoiceInfoLine.PdsCWReceiveNow - _vendInvoiceInfoLine.pdsCWQtyMatched();
                toReceiveNowInvent      = PdsCatchWeight::inventQty(inventTable.ItemId, this.PdsCWReceiveNow);

                this.ReceiveNow         = EcoResProductUnitConverter::convertForReleasedProduct(
                                            inventTable.ItemId,
                                            this.InventDimId,
                                            toReceiveNowInvent,
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTable.inventUnitId()),
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.purchLine().PurchUnit),
                                            NoYes::Yes,
                                            NoYes::No);

            }

        }
        else
        {
            factor = _vendInvoiceInfoLine.PurchPrice > purchLine.PurchPrice ? 1 : -1;

            if(!_isCatchWeight)
            {
                this.ReceiveNow = (_vendInvoiceInfoLine.metIsPartialQty() ? _vendInvoiceInfoLine.ReceiveNow : _vendInvoiceInfoLine.purchQtyMatched()) * factor;
            }
            else
            {
                this.PdsCWReceiveNow    = (_vendInvoiceInfoLine.metCWIsPartialQty() ? _vendInvoiceInfoLine.PdsCWReceiveNow : _vendInvoiceInfoLine.pdsCWQtyMatched()) * factor;
                toReceiveNowInvent      = PdsCatchWeight::inventQty(inventTable.ItemId, this.PdsCWReceiveNow);

                this.ReceiveNow = EcoResProductUnitConverter::convertForReleasedProduct(
                                            inventTable.ItemId,
                                            this.InventDimId,
                                            toReceiveNowInvent,
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTable.inventUnitId()),
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.purchLine().PurchUnit),
                                            NoYes::Yes,
                                            NoYes::No);
            }
        }

        this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(_isCatchWeight, UnknownNoYes::Yes);
    }

    /// <summary>
    /// Reset receipted invoice line
    /// </summary>
    /// <returns>True if price reset only; otherwise false</returns>
    /// <param name = "_priceResetOnly">Only price reset</param>
    public void metResetReceiptedInvoiceLine(boolean _priceResetOnly = false)
    {
        boolean                 useCatchWeight          = this.PdsCWReceiveNow ? true : false;

        this.PurchPrice         = this.purchLine().PurchPrice;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        if(!_priceResetOnly)
        {
            this.PdsCWReceiveNow    = this.pdsCWQtyMatched();
            this.ReceiveNow         = this.purchQtyMatched();
            this.ReasonTableRef     = 0;
            this.MetPriceVarianceReasonCode = 0;

            this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(useCatchWeight, UnknownNoYes::Yes);
            this.modifiedField(fieldNum(VendInvoiceInfoLine, ReceiveNow));
        }

        if(this.validateWrite())
        {
            this.update();
        }
    }

/// <summary>
/// Checks if invoice quantity is less than product receipt quantity matched. 
/// </summary>
/// <returns>True if quantities are equal; otherwise false</returns>
public boolean metIsPartialQty()
{
    return this.ReceiveNow < this.purchQtyMatched();
}

/// <summary>
/// Checks if CW invoice quantity is less than product receipt quantity matched.
/// </summary>
/// <returns>True if quantities are equal; otherwise false</returns>
public boolean metCWIsPartialQty()
{
    return this.PdsCWReceiveNow < this.pdsCWQtyMatched();
}

public display METQuantityVariance displayQuantityVariance()
{
    return this.ReceiveNow - this.METReceiptedQuantity;
}

public display METPriceVarianceReal displayPriceVariance()
{
    return this.PurchPrice - this.METReceiptedUnit;
}

public display METCWQuantityVariance displayCWQuantityVariance()
{
    return this.PdsCWReceiveNow - this.METReceiptedCWQuantity;
}

    /// <summary>
    /// CB411_412_ChargeThrough
    /// </summary>
    /// <param name = "_cbCTInvoiceLine"><c>METCBCTInvoiceLine</c> record to initialise fields from</param>
    void METInitFromCBCTInvoiceLine(METCBCTInvoiceLine _cbCTInvoiceLine)
    {
        this.Description        = _cbCTInvoiceLine.Description;
        this.ItemId             = _cbCTInvoiceLine.ItemId;
        this.ReceiveNow         = _cbCTInvoiceLine.Qty;
        this.PurchPrice         = _cbCTInvoiceLine.Amount;
        this.TaxGroup           = _cbCTInvoiceLine.TaxGroup;
        this.TaxItemGroup       = _cbCTInvoiceLine.TaxItemGroup;
        this.DefaultDimension   = _cbCTInvoiceLine.FinancialDimension;

        InventDim inventDim;
        inventDim.InventSiteId  = _cbCTInvoiceLine.InventSiteId;
        inventDim.InventLocationId = _cbCTInvoiceLine.InventLocationId;
        inventDim = InventDim::findOrCreate(inventDim);
        this.InventDimId        = inventDim.inventDimId;
    }
